// frontend/src/components/Dashboard.jsx

import React, { useEffect, useState, useRef } from "react";
import { io } from "socket.io-client";

import {
  fetchStats,
  fetchFraudCycles,
  fetchRiskLogs,
  fetchTraders,
} from "../services/api";

import GraphView from "./GraphView";
import FraudTable from "./FraudTable";
import TraderCard from "./TraderCard";
import RiskHeatmap from "./RiskHeatmap";
import InsertTradeForm from "./InsertTradeForm";

const SOCKET_URL = "http://localhost:5000";

export default function Dashboard() {
  const [stats, setStats] = useState(null);
  const [cycles, setCycles] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [traders, setTraders] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [flashRed, setFlashRed] = useState(false);

  const socketRef = useRef(null);

  useEffect(() => {
    // Initial Data Load
    fetchStats().then(setStats);
    fetchFraudCycles().then((d) => setCycles(d.cycles || []));
    fetchRiskLogs().then(setRiskLogs);
    fetchTraders().then(setTraders);

    // WebSocket Setup
    socketRef.current = io(SOCKET_URL);

    socketRef.current.on("fraud_alert", (newAlerts) => {
      setAlerts((prev) => [...newAlerts, ...prev].slice(0, 10));

      // Flash effect 🌋
      setFlashRed(true);
      setTimeout(() => setFlashRed(false), 2000);
    });

    return () => socketRef.current?.disconnect();
  }, []);

  return (
    <div
      style={{
        background: flashRed ? "#1a0000" : "#0f172a",
        transition: "background 0.3s",
        minHeight: "100vh",
        padding: "24px",
        color: "#f1f5f9",
      }}
    >
      {/* 🚨 Real-time Alert Banner */}
      {alerts.length > 0 && (
        <div
          style={{
            background: "#ef4444",
            padding: "12px",
            borderRadius: "8px",
            marginBottom: "20px",
          }}
        >
          🚨 <strong>FRAUD ALERT:</strong> {alerts[0]?.reason}
        </div>
      )}

      {/* 📊 Overview Stats */}
      {stats && (
        <div
          style={{
            display: "flex",
            gap: "16px",
            marginBottom: "32px",
          }}
        >
          {[
            { label: "Total Trades", value: stats.total_trades },
            { label: "High Risk Trades", value: stats.high_risk_trades },
            { label: "High Risk Traders", value: stats.high_risk_traders },
            { label: "Total Fraud Logs", value: stats.total_fraud_logs },
          ].map((s) => (
            <div
              key={s.label}
              style={{
                flex: 1,
                background: "#1e293b",
                padding: "20px",
                borderRadius: "10px",
              }}
            >
              <p
                style={{
                  margin: 0,
                  color: "#94a3b8",
                  fontSize: "0.85rem",
                }}
              >
                {s.label}
              </p>
              <h2 style={{ margin: 0, fontSize: "2rem" }}>{s.value}</h2>
            </div>
          ))}
        </div>
      )}

      {/* 🔍 Graph */}
      <h2>🔍 Trading Network Graph</h2>
      {cycles.length > 0 ? (
        <GraphView cycles={cycles} />
      ) : (
        <p>No fraud cycles detected.</p>
      )}

      {/* ⚠️ Risk Logs */}
      <h2 style={{ marginTop: "32px" }}>⚠️ Risk Log</h2>
      <FraudTable logs={riskLogs} />

      {/* 👤 High Risk Traders */}
      <h2 style={{ marginTop: "32px" }}>👤 High Risk Traders</h2>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
          gap: "16px",
        }}
      >
        {traders
          .filter((t) => t.trust_score < 60)
          .slice(0, 12)
          .map((t) => (
            <TraderCard key={t.trader_id} trader={t} />
          ))}
      </div>

      {/* 📊 Risk Heatmap */}
      <h2 style={{ marginTop: "32px" }}>
        📊 Trader Risk Distribution
      </h2>
      <RiskHeatmap />

      {/* ➕ Insert Trade */}
      <h2 style={{ marginTop: "32px" }}>
        ➕ Live Trade Insertion
      </h2>
      <InsertTradeForm
        onInserted={() => fetchStats().then(setStats)}
      />
    </div>
  );
}
